-- USD→EUR monthly average reference rates.
-- Source: European Central Bank, series EXR.M.USD.EUR.SP00.A (monthly average, USD per 1 EUR),
--   https://data-api.ecb.europa.eu/service/data/EXR/M.USD.EUR.SP00.A
-- Fetched 2026-11-18. eur_per_unit = 1 / usd_per_eur. 106 months, 2018-01 to 2026-10.
on conflict (month, currency) do update set usd_per_eur = excluded.usd_per_eur, eur_per_unit = excluded.eur_per_unit;
